CREATE TABLE IF NOT EXISTS sales_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, order_no VARCHAR(100) NOT NULL, customer_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', total_amount NUMERIC(15,2) DEFAULT 0, order_date TIMESTAMP WITH TIME ZONE, notes TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_so_enterprise ON sales_orders(enterprise_id); CREATE TABLE IF NOT EXISTS sales_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL, material_id UUID NOT NULL, quantity INT NOT NULL, unit_price NUMERIC(15,2), shipped_qty INT DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_soi_order ON sales_order_items(order_id);